import { test, expect, Page, BrowserContext } from '@playwright/test';

test.describe('Username Pre-fill on Login Page', () => {
  let context: BrowserContext;
  let page: Page;
  const testUsername = 'testuser@example.com';
  const testPassword = 'SecurePassword123!';
  const loginUrl = 'http://localhost:3000/login';
  const dashboardUrl = 'http://localhost:3000/dashboard';

  test.beforeEach(async ({ browser }) => {
    context = await browser.newContext();
    page = await context.newPage();
  });

  test.afterEach(async () => {
    await context.close();
  });

  test('should pre-fill username after successful login and returning to login page', async () => {
    // Navigate to login page
    await page.goto(loginUrl);

    // Fill in login credentials
    const usernameInput = page.getByLabel(/username|email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    await usernameInput.fill(testUsername);
    await passwordInput.fill(testPassword);
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL(dashboardUrl);
    expect(page.url()).toContain('dashboard');

    // Verify user is logged in by checking for logout button
    const logoutButton = page.getByRole('button', { name: /logout|sign out/i });
    await expect(logoutButton).toBeVisible();

    // Navigate back to login page
    await page.goto(loginUrl);

    // Verify username is pre-filled
    const prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(testUsername);

    // Verify password field is empty for security
    const prefilledPassword = await passwordInput.inputValue();
    expect(prefilledPassword).toBe('');
  });

  test('should clear pre-filled username when user explicitly clears it', async () => {
    // Navigate to login page
    await page.goto(loginUrl);

    // Fill in login credentials
    const usernameInput = page.getByLabel(/username|email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    await usernameInput.fill(testUsername);
    await passwordInput.fill(testPassword);
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL(dashboardUrl);

    // Navigate back to login page
    await page.goto(loginUrl);

    // Verify username is pre-filled
    let prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(testUsername);

    // Clear the username field
    await usernameInput.clear();
    prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe('');

    // Fill in a different username
    const differentUsername = 'anotheruser@example.com';
    await usernameInput.fill(differentUsername);
    await passwordInput.fill(testPassword);
    await loginButton.click();

    // Wait for potential error or navigation
    await page.waitForTimeout(1000);

    // Navigate back to login page
    await page.goto(loginUrl);

    // Verify the new username is now pre-filled
    prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(differentUsername);
  });

  test('should not pre-fill username on fresh browser context without prior login', async () => {
    // Create a new context without any stored data
    const freshContext = await page.context().browser()?.newContext();
    const freshPage = await freshContext!.newPage();

    // Navigate to login page
    await freshPage.goto(loginUrl);

    // Verify username field is empty
    const usernameInput = freshPage.getByLabel(/username|email/i);
    const prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe('');

    await freshPage.close();
    await freshContext?.close();
  });

  test('should maintain username pre-fill across multiple page reloads', async () => {
    // Navigate to login page
    await page.goto(loginUrl);

    // Fill in login credentials
    const usernameInput = page.getByLabel(/username|email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    await usernameInput.fill(testUsername);
    await passwordInput.fill(testPassword);
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL(dashboardUrl);

    // Navigate back to login page
    await page.goto(loginUrl);

    // Verify username is pre-filled
    let prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(testUsername);

    // Reload the page
    await page.reload();

    // Verify username is still pre-filled after reload
    prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(testUsername);

    // Reload again
    await page.reload();

    // Verify username persists
    prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(testUsername);
  });

  test('should handle special characters in pre-filled username', async () => {
    const specialUsername = 'user+test@example.co.uk';

    // Navigate to login page
    await page.goto(loginUrl);

    // Fill in login credentials with special characters
    const usernameInput = page.getByLabel(/username|email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /login|sign in/i });

    await usernameInput.fill(specialUsername);
    await passwordInput.fill(testPassword);
    await loginButton.click();

    // Wait for navigation or error
    await page.waitForTimeout(1000);

    // Navigate back to login page
    await page.goto(loginUrl);

    // Verify special characters are preserved in pre-filled username
    const prefilledUsername = await usernameInput.inputValue();
    expect(prefilledUsername).toBe(specialUsername);
  });
});
